import sys, json

def refund(price, days_since_delivery, category, opened, damaged, shipping):
    if days_since_delivery > 30:
        return 0.0                                   # outside the window
    amount = price
    if category == "electronics" and opened and not damaged:
        amount -= round(price * 0.15, 2)             # restocking fee
    if damaged:
        amount += shipping                           # refund shipping too
    return round(amount, 2)

