# test_set: list of {"question": ..., "relevant_ids": {...}}
def recall_at_k(test_set, search_fn, k=5):
    hits = 0
    for case in test_set:
        retrieved = search_fn(case["question"])[:k]    # list of chunk ids
        if case["relevant_ids"] & set(retrieved):      # any correct chunk found?
            hits += 1
    return hits / len(test_set)

