import re

def run_tool(name, args, user):
    try:
        if name == "get_order":
            oid = args.get("order_id", "")
            if not re.fullmatch(r"\d{4,6}", oid):        # validate format
                raise ValueError("order_id must be 4 to 6 digits")
            order = db.fetch_order(oid, timeout=3)
            if order is None or order["customer_id"] != user.id:  # authorize
                raise LookupError("order not found for this account")
            return {"content": json.dumps(order)}
        raise ValueError(f"unknown tool {name}")
    except Exception as e:
        return {"content": str(e), "is_error": True}      # model sees the error

