def run_agent(question, user, tools, max_turns=8):
    messages = [{"role": "user", "content": question}]
    for turn in range(max_turns):                      # hard cap on turns
        resp = client.messages.create(model=MODEL, max_tokens=1024,
                                      tools=tools, messages=messages)
        log_trace(turn, resp)                          # save every step
        if resp.stop_reason != "tool_use":
            return "".join(b.text for b in resp.content if b.type == "text")
        messages.append({"role": "assistant", "content": resp.content})
        results = []
        for b in resp.content:
            if b.type == "tool_use":
                out = run_tool(b.name, b.input, user)
                results.append({"type": "tool_result", "tool_use_id": b.id, **out})
        messages.append({"role": "user", "content": results})
    return "Sorry, I could not finish this. A person will follow up."  # safe fallback

MAX_REFUND = 300.00

def propose_refund(order_id, amount, reason, user):
    if amount > MAX_REFUND:                           # hard limit in code
        return {"content": "Refunds over $300 need a manager.", "is_error": True}
    pending = db.create_pending_action(               # nothing is paid yet
        kind="refund", order_id=order_id, amount=amount,
        reason=reason, requested_by=user.id)
    return {"content": f"Refund proposal {pending.id} is waiting for approval."}

def approve(pending_id, approver):
    p = db.get_pending_action(pending_id)
    payments.refund(order_id=p.order_id, amount=p.amount,
                    idempotency_key=f"refund-{p.order_id}-{p.id}")  # safe to retry
    db.mark_done(pending_id, approved_by=approver.id)  # audit trail

