import sys, json

THRESHOLDS = {"refuse": 0.95, "product_rules": 0.85, "tax": 0.85, "account_ops": 0.85}

scores = json.load(open("latest_scores.json"))   # {"refuse": 0.97, "tax": 0.83, ...}
failed = {s: v for s, v in scores.items() if v < THRESHOLDS.get(s, 0.85)}

for s, v in scores.items():
    mark = "FAIL" if s in failed else "ok"
    print(f"{s:15s} {v:.2f}  (min {THRESHOLDS.get(s, 0.85):.2f})  {mark}")

sys.exit(1 if failed else 0)                     # non-zero exit blocks the merge
